```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // Read the clock once so `date` and `started` describe the same instant.
        let now = wall_clock::now();
        let secs = now.seconds;
        RunInfo {
            date: civil_date(secs),
            started: secs,
        }
    }
}

/// Formats the UTC calendar date of a Unix timestamp as `YYYY-MM-DD`.
/// Uses the proleptic Gregorian algorithm from Howard Hinnant's `civil_from_days`.
fn civil_date(secs: u64) -> String {
    let z = (secs / 86_400) as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }
    format!("{:04}-{:02}-{:02}", year, month, day)
}

export!(Node);
